const CREATOR_CODES = { m: 'music', d: 'dj', w: 'writer' };

function seedEntities() {
  return ROWS.map(([name, kind, creators, country, url, submission, model, tier, noteKey]) => ({
    name,
    kind,
    creatorTypes: [...creators].map((c) => CREATOR_CODES[c]),
    country,
    url,
    submission,
    model,
    tier,
    noteKey,
    note: NOTES[noteKey],
  }));
}

module.exports = { seedEntities, ROWS, NOTES };
